import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
  // Given I am signed in as member@northwind.test
  const member = await apiAs("member");

  // And a draft vendor with only an extracted w9 document
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Rev02 Vendor"), category: "logistics", contact_email: "ap@harborline.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();
  expect(vendor.status).toBe("draft");

  const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "w9",
      file: { name: "w9.txt", mimeType: "text/plain", buffer: fs.readFileSync(sample("w9.txt")) },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const doc = await upload.json();

  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/documents/${doc.id}`);
        return (await res.json()).status;
      },
      { timeout: 30_000, message: "w9 document should finish extraction" },
    )
    .toBe("extracted");

  // When I submit the vendor for review
  const res = await member.post(`/api/vendors/${vendor.id}/submit`);
  const bodyText = await res.text();

  // Then the response status is 409
  expect(res.status(), bodyText).toBe(409);
  const body = JSON.parse(bodyText);
  // And the error code is documents_incomplete
  expect(body.error.code, bodyText).toBe("documents_incomplete");
  // And the error lists missing kinds contract and insurance_certificate
  expect([...body.error.missing_kinds].sort(), bodyText).toEqual(["contract", "insurance_certificate"]);
});
